import logging
import logging.config

LOGGING_CONFIG = {
    "version": 1,
    "disable_existing_loggers": False,
    "formatters": {
        "json": {
            # reference the custom formatter class by dotted path
            "()": "__main__.JsonFormatter",
        },
    },
    "handlers": {
        "stdout": {
            "class": "logging.StreamHandler",
            "formatter": "json",
            "level": "INFO",
        },
    },
    "loggers": {
        "pipeline": {"handlers": ["stdout"], "level": "INFO", "propagate": False},
    },
}

logging.config.dictConfig(LOGGING_CONFIG)
base_logger = logging.getLogger("pipeline")

# Bind a run_id to every record without repeating extra= on each call
run_logger = logging.LoggerAdapter(base_logger, {"run_id": "r-2026-07-02"})

run_logger.info("extract started", extra={"source": "crm"})
run_logger.info("load finished", extra={"rows": 1820})
